dmcaVideoSearch.query:
select jsonb_build_object(
'functions', (select jsonb_agg(jsonb_build_object(
'name', p.proname, 'identity_arguments', pg_get_function_identity_arguments(p.oid),
'language', l.lanname, 'security_definer', p.prosecdef, 'volatility', p.provolatile,
'config', p.proconfig, 'acl', p.proacl::text,
'body_sha256', encode(sha256(convert_to(p.prosrc, 'UTF8')), 'hex'),
'body_bytes', octet_length(p.prosrc)
) order by p.proname)
from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang
where n.nspname='public' and p.proname in ('dmca_next_case_number','submit_dmca_notice','enqueue_dmca_attachment_scan','search_public_people')),
'official_video_rls', (select jsonb_build_object('rls', c.relrowsecurity, 'force_rls', c.relforcerowsecurity, 'acl', c.relacl::text,
'policies', (select jsonb_agg(jsonb_build_object('name',pol.polname,'command',pol.polcmd,'permissive',pol.polpermissive,
'roles',pol.polroles::text,'using',pg_get_expr(pol.polqual,pol.polrelid),'check',pg_get_expr(pol.polwithcheck,pol.polrelid)) order by pol.polname)
from pg_policy pol where pol.polrelid=c.oid))
from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='official_rachi_original_videos')
) as reconciliation_catalog;
